import gzip,hashlib,json
from pathlib import Path
r=Path(__file__).resolve().parents[2];sha=lambda b:hashlib.sha256(b).hexdigest()
rows={
't0-shared-product':('Shared immutable letter product saves 128 raw expected Toffolis','21 native tests pass. The phase oracle owns the letter AND through fold and cleanup, while the fold borrows it. Complete raw peak/touched width is 1,233; builder expected Toffolis 762,882.25. Candidate raw SHA 8d458cf4cfbf340264c41a33d1ca4e7fae203420690bcc6dc09cbe2f9ed2ad4f. Control remains byte-exact 13f6ffc3.'),
'fin1-loan-native':('Thirty-helper prefix compressed to twenty retained forms','Four native tests pass: the new fin1 prefix roundtrip, two existing core-loan controls and the original prefix control. Full 16,384 source assignments, guards, independent measurement coefficients and uninterrupted replay are covered. Nine garbage helpers have Clifford erasure; one carry needs one conditional temporary AND. Regeneration uses eleven ANDs. This is a component storage result.'),
'fin1-fold':('Native fin1 fold passes; first complete Q1232 attempt fails','22 native tests pass. Raw cap1234 and cap1233 remain exact controls; cap1232 fails its unchanged capacity assertion at reverse round126. The supervisor finishes its sweep successfully, but the failed candidate has exit101 and is not a complete circuit.'),
'reverse-plan7':('Exact seven-carry reverse schedule clears one capacity failure','24 native test executions pass, covering23 unique tests because the old plan7 filter also matches the new module. Three-cap sweep preserves old controls; cap1232 then fails the next reverse round125 capacity assertion. No complete candidate or resource improvement.'),
'reverse-budget':('Complete raw Q1232 circuit after validated reverse budgets','23 native tests pass, including the exact reverse budgets7/8/9, shared affine sources, guards, inverse and independent measurement coefficients. Complete raw peak/touched width is1,232, builder expected763,623.1. Raw SHA23acf8d486739226e3bc2a9b255fa95e27670cd2f54a154a923ed92f647c37e0. Cap1234/control and cap1233 streams remain byte-exact. These are raw construction diagnostics.'),
'generic-postpass':('Generic exact passes audited separately from frozen certificates','The official baseline exactly reproduces125deb3a. Generic control depth weight761,696.25 and candidate Q1233 depth weight762,347.25 are diagnostic, not mean executed Toffolis. The generic chain omits source-bound tables, census cuts and identity tail. Original raw compressed-hash assertion failure is retained; v2 compares identical uncompressed operation records because the diagnostic writer uses a different zstd window.'),
'truth14':('Fourteen-variable proof engine passes but saves only two Toffolis','10 native tests pass, with scalar reference functions, exhaustive bit-map proofs through14 variables and48 guarded measurement circuits across all1,024 inputs. Frozen generic Q1233 input is optimized by two CCX-to-CX rewrites; diagnostic depth weight falls762,347.25 to762,345.25. No additional classical-factor saving. Phase and values are preserved by the proven rewrite mechanism; no scratch is added.'),
'replay-layout-audit':('Audit refutes unchanged replay-boundary claim','Metadata-only generation reproduces all three raw stream hashes. Cap1234 has2,213 recorded sites; cap1233 has2,255 and cap1232 has2,297. Both the ordered trace and site multisets differ: respectively586/628 and918/1,002 old/new-only sites. Trace covers existing record_replay_site calls only. Fixed direct profile constants do not establish fixed derived approximation predicates.'),
}
correction='Direct cut/profile constants were kept fixed, but changing the global budget changes derived replay chunk boundaries. The layout audit preserves exact streams and differing traces. Earlier statements that all arithmetic windows/predicates stayed unchanged were too broad. Component equivalence proofs remain valid; they do not establish full point-addition equivalence. A complete correctness comparison is required before qualification.'
for short,(title,text) in rows.items():
 p=r/'experiments'/f'breakthrough-{short}-20261020';assert(p/'LOCAL-VERIFICATION.json').exists();assert not(p/'STATUS.md').exists()
 (p/'STATUS.md').write_bytes(('# '+title+'\n\n'+text+'\n\n'+correction+'\n\nAll archive members were independently hash-verified locally. Frozen source, protected17-file checks, native logs and negative outcomes are retained. No new complete benchmark, final statistical gate, nonce search, submission or scored improvement is claimed.\n').encode())
 (p/'.gitattributes').write_bytes(b'* -text\n');(p/'.gitignore').write_bytes(b'/observer/\n/primitive/\n/tool/\n/evidence.tar.gz\n')
p=r/'experiments/breakthrough-core-loan-preflight-20261020/STATUS.md';p.write_bytes(p.read_bytes()+b'\n## Replay-scope correction\n\n'+correction.encode()+b'\n')
b=r/'experiments/breakthrough-assessment-20261020';latest=json.loads((b/'LATEST.json').read_bytes());p=b/latest['snapshot'];assert not(p/'SNAPSHOT-MANIFEST.json').exists();raw=(p/'public-submissions.json').read_bytes();(p/'public-submissions.json.gz').write_bytes(gzip.compress(raw,mtime=0));files=['leader-product.json','leader-qubits.json','leader-toffoli.json','PUBLIC-RECORDS.json','public-submissions.json.gz'];(p/'SNAPSHOT-MANIFEST.json').write_bytes((json.dumps({'raw_api_sha256':sha(raw),'files':{n:sha((p/n).read_bytes())for n in files},'scope':'Fresh immutable public snapshot. Prior snapshots remain historical evidence.'},indent=2)+'\n').encode());(p/'.gitattributes').write_bytes(b'* -text\n')
